from __future__ import annotations

import argparse
import json
import re
import subprocess
from pathlib import Path
from typing import Any


def _run(cmd: list[str], *, cwd: Path) -> dict[str, Any]:
    try:
        proc = subprocess.run(cmd, cwd=str(cwd), text=True, capture_output=True)
        return {
            "command": cmd,
            "returncode": proc.returncode,
            "stdout": proc.stdout,
            "stderr": proc.stderr,
            "ok": proc.returncode == 0,
        }
    except OSError as exc:
        return {
            "command": cmd,
            "returncode": 127,
            "stdout": "",
            "stderr": f"{type(exc).__name__}: {exc}",
            "ok": False,
        }


def _git_lines(repo: Path, *args: str) -> list[str]:
    result = _run(["git", *args], cwd=repo)
    if not result["ok"]:
        raise RuntimeError(result["stderr"].strip() or "git command failed")
    return [line.strip() for line in result["stdout"].splitlines() if line.strip()]


def _changed_paths(repo: Path, base_ref: str) -> list[str]:
    return _git_lines(repo, "diff", "--name-only", f"{base_ref}...HEAD")


def _diff_text(repo: Path, base_ref: str) -> str:
    result = _run(["git", "--no-pager", "diff", "--no-ext-diff", f"{base_ref}...HEAD"], cwd=repo)
    if not result["ok"]:
        raise RuntimeError(result["stderr"].strip() or "git diff failed")
    return result["stdout"]


def _repo_uses_native_mysql_prepares(repo: Path) -> bool:
    for path in repo.rglob("*.php"):
        if ".git" in path.parts:
            continue
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if "PDO::ATTR_EMULATE_PREPARES" in text and re.search(
            r"PDO::ATTR_EMULATE_PREPARES\s*=>\s*false", text, flags=re.IGNORECASE
        ):
            return True
    return False


def _duplicate_named_placeholders(path: Path) -> list[dict[str, Any]]:
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return []

    findings: list[dict[str, Any]] = []
    # Conservative heuristic for literal SQL passed directly to prepare().
    for match in re.finditer(
        r"->prepare\(\s*(['\"])(?P<sql>.*?)(?<!\\)\1\s*\)",
        text,
        flags=re.DOTALL,
    ):
        sql = match.group("sql")
        names = re.findall(r"(?<!:):([A-Za-z_][A-Za-z0-9_]*)", sql)
        duplicates = sorted({name for name in names if names.count(name) > 1})
        if duplicates:
            findings.append(
                {
                    "line": text.count("\n", 0, match.start()) + 1,
                    "placeholders": duplicates,
                    "sql_excerpt": sql[:500],
                }
            )
    return findings


def _syntax_check(repo: Path, rel_path: str) -> dict[str, Any] | None:
    path = repo / rel_path
    if not path.exists() or not path.is_file():
        return None
    suffix = path.suffix.lower()
    if suffix == ".php":
        return _run(["php", "-l", rel_path], cwd=repo)
    if suffix == ".py":
        return _run(["python3", "-m", "py_compile", rel_path], cwd=repo)
    if suffix in {".sh", ".bash"}:
        return _run(["bash", "-n", rel_path], cwd=repo)
    if suffix == ".json":
        return _run(["python3", "-m", "json.tool", rel_path], cwd=repo)
    return None


def verify(repo: Path, base_ref: str, handoff: dict[str, Any]) -> tuple[dict[str, Any], str]:
    changed = _changed_paths(repo, base_ref)
    diff = _diff_text(repo, base_ref)
    target_paths = {str(item) for item in handoff.get("target_paths", [])}
    forbidden_paths = {str(item) for item in handoff.get("forbidden_paths", [])}

    blockers: list[dict[str, Any]] = []
    warnings: list[dict[str, Any]] = []
    checks: list[dict[str, Any]] = []

    diff_check = _run(["git", "diff", "--check", f"{base_ref}...HEAD"], cwd=repo)
    checks.append({"name": "git_diff_check", **diff_check})
    if not diff_check["ok"]:
        blockers.append({
            "code": "DIFF_CHECK_FAILED",
            "message": "git diff --check meldet Fehler.",
            "evidence": (diff_check["stdout"] + diff_check["stderr"])[-4000:],
        })

    if not changed:
        blockers.append({
            "code": "EMPTY_DIFF",
            "message": "Der Ergebnisbranch enthält gegenüber dem Basisstand keine Änderungen.",
        })

    forbidden_changed = sorted(set(changed) & forbidden_paths)
    if forbidden_changed:
        blockers.append({
            "code": "FORBIDDEN_PATH_CHANGED",
            "message": "Explizit verbotene Pfade wurden geändert.",
            "paths": forbidden_changed,
        })

    unexpected = sorted(path for path in changed if target_paths and path not in target_paths)
    if unexpected:
        warnings.append({
            "code": "UNEXPECTED_PATHS",
            "message": "Es wurden Pfade außerhalb des Handoff-Ziels geändert; Heavy Review muss das begründen.",
            "paths": unexpected,
        })

    missing_targets = sorted(path for path in target_paths if not (repo / path).exists())
    if missing_targets:
        blockers.append({
            "code": "TARGET_PATH_MISSING",
            "message": "Mindestens ein verbindlicher Zielpfad fehlt im Ergebnisbranch.",
            "paths": missing_targets,
        })

    syntax_results: list[dict[str, Any]] = []
    for rel_path in changed:
        result = _syntax_check(repo, rel_path)
        if result is None:
            continue
        entry = {"path": rel_path, **result}
        syntax_results.append(entry)
        if not result["ok"]:
            blockers.append({
                "code": "SYNTAX_CHECK_FAILED",
                "message": f"Syntax-/Formatprüfung fehlgeschlagen: {rel_path}",
                "path": rel_path,
                "evidence": (result["stdout"] + result["stderr"])[-4000:],
            })
    checks.append({"name": "syntax_checks", "results": syntax_results, "ok": all(r["ok"] for r in syntax_results)})

    native_prepares = _repo_uses_native_mysql_prepares(repo)
    duplicate_pdo: list[dict[str, Any]] = []
    if native_prepares:
        for rel_path in changed:
            if not rel_path.endswith(".php"):
                continue
            for finding in _duplicate_named_placeholders(repo / rel_path):
                duplicate_pdo.append({"path": rel_path, **finding})
        if duplicate_pdo:
            blockers.append({
                "code": "DUPLICATE_NATIVE_PDO_PLACEHOLDER",
                "message": (
                    "Dasselbe benannte PDO-Placeholder wird innerhalb eines prepare()-Statements mehrfach verwendet, "
                    "obwohl native Prepares aktiv sind (ATTR_EMULATE_PREPARES=false)."
                ),
                "findings": duplicate_pdo,
            })
    checks.append({
        "name": "native_pdo_duplicate_placeholders",
        "native_prepares": native_prepares,
        "findings": duplicate_pdo,
        "ok": not duplicate_pdo,
    })

    report = {
        "schema": 1,
        "ok": not blockers,
        "base_ref": base_ref,
        "head": _git_lines(repo, "rev-parse", "HEAD")[0],
        "changed_paths": changed,
        "target_paths": sorted(target_paths),
        "forbidden_paths": sorted(forbidden_paths),
        "blockers": blockers,
        "warnings": warnings,
        "checks": checks,
        "acceptance_requirements": {
            "task": handoff.get("task", ""),
            "requested_changes": handoff.get("requested_changes", []),
            "constraints": handoff.get("constraints", []),
            "tests": handoff.get("tests", []),
        },
    }
    return report, diff


def main() -> int:
    parser = argparse.ArgumentParser(description="Deterministische Post-Main-Verifikation")
    parser.add_argument("--repo", required=True)
    parser.add_argument("--base-ref", required=True)
    parser.add_argument("--handoff", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--diff-output", required=True)
    args = parser.parse_args()

    repo = Path(args.repo).resolve()
    handoff = json.loads(Path(args.handoff).read_text(encoding="utf-8"))
    report, diff = verify(repo, args.base_ref, handoff)

    Path(args.output).write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    Path(args.diff_output).write_text(diff, encoding="utf-8")

    print(f"[VERIFY] changed_paths: {', '.join(report['changed_paths']) or '(keine)'}")
    print(f"[VERIFY] blockers: {len(report['blockers'])}, warnings: {len(report['warnings'])}")
    print(f"[VERIFY] Ergebnis: {'PASS' if report['ok'] else 'FAIL'}")
    print(f"[VERIFY] Report: {args.output}")
    print(f"[VERIFY] Diff: {args.diff_output}")
    return 0 if report["ok"] else 20


if __name__ == "__main__":
    raise SystemExit(main())
